INSERT INTO collection_pages VALUES('e62b00bfbe9456cc9a75d85c40693d8877aae503a4e656e7314e4b8582c9ab23','b940ed2455389a6e4cb27ca8753d521fccb581a813b1f5086aae991aef9fcd73','{"hasNext":false,"items":[{"author":{"account":null,"email":"joshholmes@Joshs-MacBook-Pro.local","name":"Josh Holmes"},"authoredDate":"2025-10-31T17:23:56Z","committedDate":"2025-10-31T17:23:56Z","committer":{"account":null,"email":"joshholmes@Joshs-MacBook-Pro.local","name":"Josh Holmes"},"observedAt":"2026-10-08T20:46:52.423Z","repositoryId":1087300782,"sha":"bdc0f1e3fa9ebf9414ba320bb499de0b681af739"}],"observedAt":"2026-10-08T20:46:52.423Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/Aon-Intelligence/dualhosts/commits/bdc0f1e3fa9ebf9414ba320bb499de0b681af739/comments","commit":{"author":{"date":"2025-10-31T17:23:56Z","email":"joshholmes@Joshs-MacBook-Pro.local","name":"Josh Holmes"},"comment_count":0,"committer":{"date":"2025-10-31T17:23:56Z","email":"joshholmes@Joshs-MacBook-Pro.local","name":"Josh Holmes"},"message":"Initial commit: Multi-container micro-frontend architecture with Host-owned auth\n\nArchitecture:\n- Host (Python/Flask): Main shell, owns auth/session/navigation\n- Secondary (Node.js/Express): Feature micro-frontend\n- Third (.NET 9/ASP.NET Core): Feature micro-frontend\n- Gateway (Nginx): Reverse proxy for same-origin access\n- Redis: Shared session storage\n\nFeatures:\n- Unified authentication (single sign-on across all apps)\n- Web Component integration (default) + iFrame fallback\n- Auth-aware micro-frontends with reactive indicators\n- Shared design system (CSS custom properties)\n- Database queries execute as authenticated user\n- Zero token exposure (security-first)\n\nTesting:\n- 37+ automated tests\n- Integration, unit, and auth indicator tests\n- Comprehensive test coverage\n\nDocumentation:\n- Interface specifications (host & client contracts)\n- Architecture overview and integration playbooks\n- Security and compliance notes\n- Local development runbooks","tree":{"sha":"3b50bda8b2b7a7e07377cc69376bf85c549d478b","url":"https://api.github.com/repos/Aon-Intelligence/dualhosts/git/trees/3b50bda8b2b7a7e07377cc69376bf85c549d478b"},"url":"https://api.github.com/repos/Aon-Intelligence/dualhosts/git/commits/bdc0f1e3fa9ebf9414ba320bb499de0b681af739","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Aon-Intelligence/dualhosts/commit/bdc0f1e3fa9ebf9414ba320bb499de0b681af739","node_id":"C_kwDOQM7krtoAKGJkYzBmMWUzZmE5ZWJmOTQxNGJhMzIwYmI0OTlkZTBiNjgxYWY3Mzk","parents":[],"sha":"bdc0f1e3fa9ebf9414ba320bb499de0b681af739","url":"https://api.github.com/repos/Aon-Intelligence/dualhosts/commits/bdc0f1e3fa9ebf9414ba320bb499de0b681af739"}],"requestUrl":"https://api.github.com/repos/Aon-Intelligence/dualhosts/commits?per_page=100&page=1&sha=bdc0f1e3fa9ebf9414ba320bb499de0b681af739&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A39%3A57.298Z"}');
